import sys
from bisect import bisect_left


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n, m = data[0], data[1]
    adjacency = [[] for _ in range(n)]
    minimum_left = [10**18] * n
    minimum_right = [10**18] * n
    weights = []

    for index in range(2, 2 + 3 * m, 3):
        airport = data[index] - 1
        factory = data[index + 1] - 1
        days = data[index + 2]
        adjacency[airport].append((days, factory))
        weights.append(days)
        if days < minimum_left[airport]:
            minimum_left[airport] = days
        if days < minimum_right[factory]:
            minimum_right[factory] = days

    del data

    lower_bound = max(max(minimum_left), max(minimum_right))
    if lower_bound == 10**18:
        print(-1)
        return

    for neighbors in adjacency:
        neighbors.sort()

    weights = sorted(set(weights))
    match_left = [-1] * n
    match_right = [-1] * n
    matched_days = [0] * n
    matched_count = 0

    sys.setrecursionlimit(max(1000, 2 * n + 100))

    def feasible(limit):
        nonlocal matched_count

        for airport in range(n):
            if match_left[airport] != -1 and matched_days[airport] > limit:
                match_right[match_left[airport]] = -1
                match_left[airport] = -1
                matched_count -= 1

        while matched_count < n:
            distance = [-1] * n
            queue = []
            for airport in range(n):
                if match_left[airport] == -1:
                    distance[airport] = 0
                    queue.append(airport)

            shortest = n + 1
            head = 0
            while head < len(queue):
                airport = queue[head]
                head += 1
                next_distance = distance[airport] + 1
                if next_distance > shortest:
                    continue

                for days, factory in adjacency[airport]:
                    if days > limit:
                        break
                    partner = match_right[factory]
                    if partner == -1:
                        shortest = next_distance
                    elif next_distance < shortest and distance[partner] == -1:
                        distance[partner] = next_distance
                        queue.append(partner)

            if shortest == n + 1:
                return False

            position = [0] * n

            def augment(airport):
                neighbors = adjacency[airport]
                next_distance = distance[airport] + 1

                while position[airport] < len(neighbors):
                    days, factory = neighbors[position[airport]]
                    if days > limit:
                        break
                    position[airport] += 1
                    partner = match_right[factory]

                    if partner == -1:
                        if next_distance != shortest:
                            continue
                    elif (
                        next_distance >= shortest
                        or distance[partner] != next_distance
                        or not augment(partner)
                    ):
                        continue

                    match_left[airport] = factory
                    match_right[factory] = airport
                    matched_days[airport] = days
                    return True

                distance[airport] = -1
                return False

            for airport in queue:
                if distance[airport] == 0 and match_left[airport] == -1:
                    if augment(airport):
                        matched_count += 1

        return True

    low = bisect_left(weights, lower_bound)
    high = len(weights) - 1
    answer = -1

    while low <= high:
        middle = (low + high) // 2
        if feasible(weights[middle]):
            answer = weights[middle]
            high = middle - 1
        else:
            low = middle + 1

    print(answer)


if __name__ == "__main__":
    main()
